  const defaultSourceIds = [
  "rrf-fordham-modern",
  "rrf-britannica-renaissance"
];

  function people(names, title) {
    return (names || []).map((name) => ({
      name,
      role: "关键人物/群体",
      years: "",
      color: "var(--accent-gold)",
      bio: `${name}需要放在“${title}”的制度、战争、宗教或社会背景中理解，不应只作为孤立人物记忆。`,
      events: [title]
    }));
  }

  function buildProcess(item) {
    return [
      {
        time: item.time,
        title: item.processTitles?.[0] || "结构背景",
        description: item.context || `${item.title}发生前，相关地区的政治、军事、财政或宗教结构已经积累压力；这个节点重要，是因为它把长期条件推向可见转折。`
      },
      {
        time: item.time,
        title: item.processTitles?.[1] || "事件展开",
        description: item.development || `${item.title}的展开改变了权力归属、制度运行或战争格局，使后续政治力量不得不重新安排联盟、治理和动员方式。`
      },
      {
        time: item.time,
        title: item.processTitles?.[2] || "后续影响",
        description: item.impact || `${item.title}之后，影响继续延伸到后续国家形成、帝国治理、宗教秩序或跨地区竞争中；学习时要把它放入前后因果链，而不是只背年份。`
      }
    ];
  }

  function event(item) {
    const sourceIds = item.sourceIds || defaultSourceIds;
    return {
      id: item.id,
      dynastyId,
      title: item.title,
      aliases: item.aliases || [],
      era: item.era,
      period: dynasty,
      time: item.time,
      regions: item.regions || ["欧洲", "地中海"],
      topics: item.topics || [],
      summary: item.summary,
      bookmarked: false,
      people: people(item.people, item.title),
      relations: item.relations || [],
      background: item.background || [item.context || `${item.title}需要放在${dynasty}的长期结构中理解：政治共同体、军事动员、财政能力、宗教权威和跨地区竞争共同推动了事件走向。`],
      process: item.process || buildProcess(item),
      results: item.results || [item.result || item.summary],
      debates: item.debates || [{
        view: "学习提示",
        content: item.tip || "本条先作为主线学习版本整理，重点看因果和结构变化；具体原始文本卷章后续可以继续细核。"
      }],
      claims: [{
        statement: item.claim || item.summary,
        status: "较稳妥",
        statusType: "stable",
        confidence: item.confidence || "medium",
        sourceIds,
        note: "当前绑定公开来源入口与白话释义，后续可继续补更细的原始材料卷章和现代研究页码。"
      }],
      citations: [{
        sourceId: sourceIds[0],
        reference: item.reference || "公开史料/现代概述入口",
        status: item.citationStatus || "已给公开入口，待逐条细化卷章",
        plainText: item.plainText || `白话理解：${item.summary}`,
        note: "不堆原文，先给学习者能读懂的释义；涉及古代人口、疆域和兵力数字时保留估算意识。"
      }],
      causalChain: item.causalChain || [],
      sources,
      reviewQuestions: [{
        type: "主线理解",
        question: item.question || `${item.title}为什么应放入${dynasty}主线？`,
        answer: item.answer || "因为它改变了政治结构、战争格局、制度运行或宗教文化秩序，能帮助理解前后阶段如何衔接。"
      }],
      notes: [],
      sourceStatus: "公开入口已补，细节待继续核卷"
    };
  }

